divergences.oracle:
{
	"name": "@effected/sbom",
	"version": "0.10.0",
	"private": true,
	"description": "Sigstore DSSE signing for in-toto statements; the SBOM, provenance and statement models live in @beep/sbom.",
	"keywords": [
		"sbom",
		"cyclonedx",
		"sigstore",
		"slsa",
		"provenance",
		"ntia",
		"effect",
		"effected"
	],
	"homepage": "https://github.com/spencerbeggs/effected/tree/main/packages/sbom#readme",
	"bugs": {
		"url": "https://github.com/spencerbeggs/effected/issues"
	},
	"repository": {
		"type": "git",
		"url": "git+https://github.com/spencerbeggs/effected.git",
		"directory": "packages/sbom"
	},
	"license": "MIT",
	"author": {
		"name": "C. Spencer Beggs",
		"email": "spencer@beggs.codes",
		"url": "https://spencerbeg.gs"
	},
	"sideEffects": false,
	"type": "module",
	"exports": {
		".": "./index.ts",
		"./package.json": "./package.json"
	},
	"scripts": {
		"build:dev": "node savvy.build.ts --target dev",
		"build:prod": "node savvy.build.ts --target prod",
		"prepare": "turbo run build:dev",
		"types:check": "tsc --noEmit"
	},
	"dependencies": {
		"@beep/sbom": "workspace:^",
		"@sigstore/bundle": "^5.0.0",
		"@sigstore/sign": "^5.0.0",
		"@beep/identity": "workspace:^",
		"@beep/schema": "workspace:^"
	},
	"devDependencies": {
		"@effect/platform-node": "catalog:effect",
		"@effect/vitest": "catalog:effect",
		"@savvy-web/bundler": "^2.4.22",
		"@types/node": "catalog:build",
		"effect": "catalog:effect",
		"typescript": "catalog:build"
	},
	"peerDependencies": {
		"effect": "catalog:effect:peers"
	},
	"engines": {
		"node": ">=24.11.0"
	},
	"publishConfig": {
		"access": "public",
		"directory": "dist/dev/pkg",
		"linkDirectory": true,
		"targets": {
			"npm": true
		}
  },
  "packageManager": "bun@9.9.9"
}

